pen_access": {"is_oa": true, "oa_status": "green", "oa_url": "https://eprints.soton.ac.uk/263347/1/1800000001%255B1%255D.pdf", "any_repository_has_fulltext": true}, "primary_location": {"id": "doi:10.1561/1800000001", "doi": "https://doi.org/10.1561/1800000001", "is_oa": false, "landing_page_url": "https://doi.org/10.1561/1800000001", "pdf_url": null, "source": {"id": "https://openalex.org/S73733540", "display_name": "Foundations and Trends® in Web Science", "issn_l": "1555-077X", "issn": ["1555-077X", "1555-0788"], "is_oa": false, "is_in_doaj": false, "is_core": true, "listed_in": ["cwts-core", "jufo-1", "poland-40", "russia-white-list-4"], "host_organization": "https://openalex.org/P4310318575", "host_organization_name": "Now Publishers", "host_organization_lineage": ["https://openalex.org/P4310318575", "https://openalex.org/P4310319811"], "host_organization_lineage_names": ["Now Publishers", "Emerald Publishing Limited"], "type": "journal"}, "license": null, "license_id": null, "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Foundations and Trends® in Web Science", "raw_type": "journal-article"}, "abstract": "A Framework for Web Science sets out a series of approaches to the analysis and synthesis of the World Wide Web, and other web-like information structures. A comprehensive set of research questions is outlined, together with a sub-disciplinary breakdown, emphasising the multi-faceted nature of the Web, and the multi-disciplinary nature of its study and development. These questions and approaches together set out an agenda for Web Science, the science of decentralised information systems. Web Science is required both as a way to understand the Web, and as a way to focus its development on key communicational and representational requirements. A Framework for Web Science surveys central engineering issues, such as the development of the Semantic Web, Web services and P2P. Analytic approaches to discover the Web's topology, or its graph-like structures, are examined. Finally, the Web as a technology is essentially socially embedded; therefore various issues and requirements for Web use and governance are also reviewed. A Framework for Web Science is aimed primarily at researchers and developers in the area of Web-based knowledge management and information retrieval. It will also be an invaluable reference for students in computer science at the postgraduate level, academics and industrial practitioners."}]", "excerpt_truncated": true, "source_sha256": "3687f66fb73fc09d60335a405702ca21f5c33322d7bf28495f13e88379d6d5f9", "verification_required": true, "topic_domain": "unassigned_problem", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.3390/wevj15090404", "doi:10.1561/1800000001", "openalex:W4402228815"], "source_candidates": ["https://doi.org/10.3390/wevj15090404", "https://eprints.soton.ac.uk/263347/1/1800000001%255B1%255D.pdf", "https://doi.org/10.1561/1800000001"], "source_candidate_identities": {}}

